76	        const points = Object.keys(subData)
77	            .map((groupedName) => {
78	                const dataPart = subData[groupedName];
79	
80	                // Special case: make the labels pretty!
81	                if (
82	                    indentation === 0 &&
83	                    dimensions.length === 1 &&
84	                    dimension !== 1
85	                ) {
86	                    // Example: <pid> (groupNameA+groupNameB+groupNameC+etc…)
87	                    const set = new Set();
88	                    dataPart.forEach((p) => set.add(p.name.split(':')[1]));
89	                    const groupNames =
